import json, sys, time, urllib.request, urllib.error

BASE = "http://localhost:8080"
log = lambda *a: print(*a, file=sys.stderr, flush=True)

class Client:
    def __init__(self):
        self.token = None
    def new_token(self):
        req = urllib.request.Request(BASE + "/token", method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            self.token = json.load(r)["token"]
    def get(self, path, auth=True):
        attempt = 0
        while True:
            attempt += 1
            if auth and self.token is None:
                self.new_token()
            headers = {"Authorization": "Bearer " + self.token} if auth else {}
            req = urllib.request.Request(BASE + path, headers=headers)
            try:
                with urllib.request.urlopen(req, timeout=30) as r:
                    return r.status, json.load(r)
            except urllib.error.HTTPError as e:
                body = e.read().decode("utf-8", "replace")
                if e.code == 401 and auth:
                    log("401 on", path, "- refreshing token", body[:200])
                    self.new_token()
                    continue
                if e.code == 404:
                    return 404, None
                if e.code == 429 or e.code >= 500:
                    wait = e.headers.get("Retry-After")
                    if wait is None:
                        try:
                            wait = json.loads(body).get("retry_after")
                        except Exception:
                            wait = None
                    wait = float(wait) if wait is not None else min(2 ** attempt, 60)
                    log(e.code, "on", path, "- waiting", wait, "s; body:", body[:200])
                    time.sleep(wait)
                    continue
                raise RuntimeError(f"{e.code} on {path}: {body[:300]}")
            except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
                log("network error on", path, e, "- retrying")
                time.sleep(min(2 ** attempt, 30))

def main():
    c = Client()
    orders = []
    page = 1
    pages_seen = []
    while True:
        status, data = c.get(f"/orders?page={page}")
        pages_seen.append(page)
        orders.extend(data["items"])
        log("page", page, "of", data["total_pages"], "items", len(data["items"]), "next", data["next"])
        if data["next"] is None:
            break
        page += 1
    json.dump({"pages": pages_seen, "orders": orders}, open("/tmp/recon/orders.json", "w"))
    log("total listings", len(orders))

    customers = {}
    for cid in sorted({o["customer_id"] for o in orders}):
        status, data = c.get(f"/customers/{cid}")
        customers[cid] = data if status == 200 else None
        if status == 404:
            log("customer 404", cid)
    json.dump(customers, open("/tmp/recon/customers.json", "w"))
    log("customers fetched", len(customers))

if __name__ == "__main__":
    main()
